                elif edge == 'bottom': coords.append((h - 1, t))
                elif edge == 'left': coords.append((t, 0))
                else: coords.append((t, w - 1))
            bars.update(coords)
            beams.extend((edge, r, c) for r, c in coords)

    # The sparse interior motif supplies the beam color.
    marker_colors = {grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] != background and (r, c) not in bars}
    if len(marker_colors) != 1:
        return out
    fill = next(iter(marker_colors))

    for edge, r, c in beams:
        if edge == 'top': dr, dc = 1, 0
        elif edge == 'bottom': dr, dc = -1, 0
        elif edge == 'left': dr, dc = 0, 1
        else: dr, dc = 0, -1
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] != background:
                if (rr, cc) not in bars:
