 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def get_runs(side):
        vals = ([grid[0][c] for c in range(w)] if side == 'top' else
                [grid[h-1][c] for c in range(w)] if side == 'bottom' else
                [grid[r][0] for r in range(h)] if side == 'left' else
                [grid[r][w-1] for r in range(h)])
        runs = []
        i = 0
        while i < len(vals):
            if vals[i] == background:
                i += 1
                continue
            j = i + 1
            while j < len(vals) and vals[j] == vals[i]:
                j += 1
            if j - i >= 2:
                runs.append((vals[i], i, j))
            i = j
        return runs

    edges = {side: get_runs(side) for side in ('top', 'bottom', 'left', 'right')}
    # Pair equal-length, equal-color guides on opposite edges.
    for side_a, side_b in (('top', 'bottom'), ('left', 'right')):
        for color_a, start_a, end_a in edges[side_a]:
            for color_b, start_b, end_b in edges[side_b]:
                length = end_a - start_a
                if color_a != color_b or end_b - start_b != length:
                    continue
                # Markers select slots by their coordinate along the pair.
                active = set()
                for r in range(1, h-1):
                    for c in range(1, w-1):
                        if grid[r][c] == background:
                            continue
                        axis = c if side_a == 'top' else r
                        if start_a <= axis < end_a:
                            active.add(axis - start_a)
                        elif start_b <= axis < end_b:
                            active.add(axis - start_b)
                for slot in active:
                    for side, pos in ((side_a, start_a + slot), (side_b, start_b + slot)):
                        if side == 'top':
                            r, c, dr, dc = 0, pos, 1, 0
                        elif side == 'bottom':
                            r, c, dr, dc = h-1, pos, -1, 0
                        elif side == 'left':
                            r, c, dr, dc = pos, 0, 0, 1
                        else:
                            r, c, dr, dc = pos, w-1, 0, -1
                        r += dr
                        c += dc
                        while 0 <= r < h and 0 <= c < w:
                            if grid[r][c] != background:
                                out[r][c] = 4
                                break
                            out[r][c] = next((grid[rr][cc] for rr in range(h) for cc in range(w)
                                              if grid[rr][cc] != background and
                                              not ((rr == 0 or rr == h-1) and grid[rr][cc] == color_a)
                                              and not ((cc == 0 or cc == w-1) and grid[rr][cc] == color_a)), background)
                            r += dr
                            c += dc
    return out
