    bg = max(counts, key=counts.get)

    def edge_runs(side):
        vals = ([grid[0][c] for c in range(w)] if side == 'top' else
                [grid[h-1][c] for c in range(w)] if side == 'bottom' else
                [grid[r][0] for r in range(h)] if side == 'left' else
                [grid[r][w-1] for r in range(h)])
        result = []
        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            j = i + 1
            while j < len(vals) and vals[j] == vals[i]:
                j += 1
            if j-i >= 2:
                result.append((vals[i], i, j))
            i = j
        return result

    edges = {side: edge_runs(side) for side in ('top','bottom','left','right')}
    interior = {grid[r][c] for r in range(1,h-1) for c in range(1,w-1) if grid[r][c] != bg}
    if len(interior) != 1:
        return out
    fill = next(iter(interior))

    # Bar pairs on opposite edges enable projection along rows/columns.
    for side_a, side_b in (('top','bottom'), ('left','right')):
        for ca, sa, ea in edges[side_a]:
            for cb, sb, eb in edges[side_b]:
                length = ea-sa
                if ca != cb or eb-sb != length:
                    continue
                active = set()
                for r in range(1,h-1):
                    for c in range(1,w-1):
                        if grid[r][c] == bg:
                            continue
                        axis = c if side_a == 'top' else r
                        if sa <= axis < ea:
                            active.add(axis-sa)
                        if sb <= axis < eb:
                            active.add(axis-sb)
                if side_a == 'top':
                    active.update(range(length))
                else:
                    has_marker = any(grid[r][c] != bg for r in range(1,h-1) for c in range(1,w-1)
                                     if sa <= r < ea or sb <= r < eb)
                    if has_marker:
                        active.update(range(length))
                for slot in active:
                    for side, pos in ((side_a, sa+slot), (side_b, sb+slot)):
                        if side == 'top': r,c,dr,dc = 0,pos,1,0
                        elif side == 'bottom': r,c,dr,dc = h-1,pos,-1,0
                        elif side == 'left': r,c,dr,dc = pos,0,0,1
                        else: r,c,dr,dc = pos,w-1,0,-1
                        r += dr
                        c += dc
                        while 0 < r < h-1 and 0 < c < w-1:
                            if grid[r][c] != bg:
                                if grid[r][c] == fill:
                                    out[r][c] = 4
                                break
                            out[r][c] = fill
                            r += dr
                            c += dc

    # Perpendicular guide runs also spread across their rows/columns where
    # sparse marker activity occurs within the paired span.
    for ca, sa, ea in edges['left']:
        for cb, sb, eb in edges['right']:
