    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def edge_runs(side):
        if side == 'top': values = grid[0]
        elif side == 'bottom': values = grid[-1]
        elif side == 'left': values = [grid[r][0] for r in range(h)]
        else: values = [grid[r][-1] for r in range(h)]
        result=[]; i=0
        while i < len(values):
            if values[i] == background:
                i += 1; continue
            j=i+1
            while j < len(values) and values[j] == values[i]: j += 1
            if j-i >= 2: result.append((values[i],i,j))
            i=j
        return result

    edges={side:edge_runs(side) for side in ('top','bottom','left','right')}
    for side_a, side_b in (('top','bottom'), ('left','right')):
        for guide_a, start_a, end_a in edges[side_a]:
            for guide_b, start_b, end_b in edges[side_b]:
                length=end_a-start_a
                if guide_a != guide_b or end_b-start_b != length:
                    continue
                # Markers aligned with either guide run activate the same slot
                # on both opposing guides.
                active={}
                for r in range(1,h-1):
                    for c in range(1,w-1):
                        marker=grid[r][c]
                        if marker == background: continue
                        axis=c if side_a=='top' else r
                        if start_a <= axis < end_a:
                            active[axis-start_a]=(r,c,marker)
                        if start_b <= axis < end_b:
                            active[axis-start_b]=(r,c,marker)
                for slot,(mr,mc,color) in active.items():
                    for side,pos in ((side_a,start_a+slot),(side_b,start_b+slot)):
                        if side=='top': r,c,dr,dc=0,pos,1,0
                        elif side=='bottom': r,c,dr,dc=h-1,pos,-1,0
                        elif side=='left': r,c,dr,dc=pos,0,0,1
