 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def runs(side):
        values = (grid[0] if side == 'top' else grid[h-1] if side == 'bottom' else
                  [grid[r][0] for r in range(h)] if side == 'left' else
                  [grid[r][w-1] for r in range(h)])
        result = []
        i = 0
        while i < len(values):
            if values[i] == background:
                i += 1
                continue
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if j - i >= 2:
                result.append((values[i], i, j))
            i = j
        return result

    edges = {side: runs(side) for side in ('top', 'bottom', 'left', 'right')}
    # Equal, same-color bars on opposing edges pair corresponding slots.
    for side_a, side_b in (('top', 'bottom'), ('left', 'right')):
        for color_a, start_a, end_a in edges[side_a]:
            for color_b, start_b, end_b in edges[side_b]:
                length = end_a - start_a
                if color_a != color_b or end_b - start_b != length:
                    continue
                markers_by_slot = {}
                for r in range(1, h-1):
                    for c in range(1, w-1):
                        marker = grid[r][c]
                        if marker == background:
                            continue
                        axis = c if side_a == 'top' else r
                        if start_a <= axis < end_a:
                            markers_by_slot.setdefault(axis-start_a, []).append((r,c,marker))
                        elif start_b <= axis < end_b:
                            markers_by_slot.setdefault(axis-start_b, []).append((r,c,marker))
                for slot, markers in markers_by_slot.items():
                    # Corresponding guide slots emit inward, colored by the
                    # marker occupying that relative slot; the marker is 4.
                    fill = markers[0][2]
                    for r,c,_ in markers:
                        out[r][c] = 4
                    for side, pos in ((side_a, start_a+slot), (side_b, start_b+slot)):
                        if side == 'top': r,c,dr,dc = 0,pos,1,0
                        elif side == 'bottom': r,c,dr,dc = h-1,pos,-1,0
                        elif side == 'left': r,c,dr,dc = pos,0,0,1
                        else: r,c,dr,dc = pos,w-1,0,-1
                        r += dr
                        c += dc
                        while 0 < r < h-1 and 0 < c < w-1:
                            if grid[r][c] != background:
                                break
                            out[r][c] = fill
                            r += dr
                            c += dc
    return out
