 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    def runs(side):
        if side == 'top': values = grid[0]
        elif side == 'bottom': values = grid[-1]
        elif side == 'left': values = [grid[r][0] for r in range(h)]
        else: values = [grid[r][w-1] for r in range(h)]
        result=[]; i=0
        while i < len(values):
            if values[i] == bg:
                i += 1; continue
            j=i+1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if j-i >= 2:
                result.append((values[i], i, j))
            i=j
        return result

    edges = {side:runs(side) for side in ('top','bottom','left','right')}
    for side_a, side_b in (('top','bottom'), ('left','right')):
        for guide_a, start_a, end_a in edges[side_a]:
            for guide_b, start_b, end_b in edges[side_b]:
                length=end_a-start_a
                if guide_a != guide_b or end_b-start_b != length:
                    continue
                # Sparse points activate their corresponding coordinate slot.
                active={}
                for r in range(1,h-1):
                    for c in range(1,w-1):
                        color=grid[r][c]
                        if color == bg: continue
                        axis=c if side_a=='top' else r
                        if start_a <= axis < end_a:
                            active[axis-start_a]=color
                        elif start_b <= axis < end_b:
                            active[axis-start_b]=color
                for slot, color in active.items():
                    # Extend each guide's aligned row/column, stopping at the
                    # encountered point; the point is highlighted as 4.
                    if side_a == 'top':
                        col = start_a+slot
                        for r in range(1,h-1):
                            if grid[r][col] != bg:
                                out[r][col]=4
                                break
                            out[r][col]=color
                    else:
                        row = start_a+slot
                        for c in range(1,w-1):
                            if grid[row][c] != bg:
                                out[row][c]=4
                                break
                            out[row][c]=color
                    if side_a == 'left':
                        # Matching right-guide projection proceeds from the right.
                        row = start_b+slot
                        for c in range(w-2,0,-1):
                            if grid[row][c] != bg:
                                out[row][c]=4
                                break
                            out[row][c]=color
                    else:
                        col = start_b+slot
                        for r in range(h-2,0,-1):
                            if grid[r][col] != bg:
                                out[r][col]=4
                                break
                            out[r][col]=color
    return out
