    # Matching bars on opposite borders pair their offsets. A marker lying
    # within either run's aligned span activates that slot; both bars project
    # the marker's color inward until the first non-background cell, which is 4.
    for side_a, side_b in (('top', 'bottom'), ('left', 'right')):
        for color_a, start_a, end_a in edges[side_a]:
